    def xǁSummarizerǁ_extract_largest_json_object__mutmut_orig(self, content: str) -> Optional[str]:
        """
        Extract largest balanced JSON object from content using bracket matching.
        
        Handles nested objects, strings with braces, and escaped characters correctly.
        Finds all JSON objects and returns the largest one.
        """
        objects = []
        i = 0
        
        while i < len(content):
            # Find next opening brace
            start_idx = content.find('{', i)
            if start_idx < 0:
                break
            
            # Extract balanced object starting from this position
            depth = 0
            in_string = False
            escape_next = False
            found = False
            
            for j in range(start_idx, len(content)):
                char = content[j]
                
                if escape_next:
                    escape_next = False
                    continue
                
                if char == '\\':
                    escape_next = True
                    continue
                
                if char == '"' and not escape_next:
                    in_string = not in_string
                    continue
                
                if in_string:
                    continue
                
                if char == '{':
                    depth += 1
                elif char == '}':
                    depth -= 1
                    if depth == 0:
                        obj_str = content[start_idx:j+1]
                        objects.append(obj_str)
                        i = j + 1
                        found = True
                        break
            
            if not found:
                break
        
        if not objects:
            return None
        
        # Return the largest object
        return max(objects, key=len)
    
